/* stand-in for the GameDistribution ad SDK: no ads. The game starts on SDK_ERROR and skips every ad. */
(function(){var P=function(v){return Promise.resolve(v)},N=function(){return Promise.reject(new Error('no ads'))};
window.gdsdk={showAd:N,preloadAd:N,play:function(){},openConsole:function(){},cancelAd:function(){}};
var o=window.GD_OPTIONS;if(o&&typeof o.onEvent==='function')setTimeout(function(){o.onEvent({name:'SDK_ERROR',message:'no ads'});},0);})();
